// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  random,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type InkDiffusionTextProps = Record<string, any>;

const InkDiffusionText: React.FC<InkDiffusionTextProps> = ({
  backgroundColor = "#FDFBF7",
  transparentBackground = false,
  durationInSeconds = 12,
  initialWord = "CREATE",
  definitionText = "to bring something into existence that wasn't there before",
  textColor = "#2C2A28",
  primaryParticleColor = "#8F7D6D",
  secondaryParticleColor = "#D4C7BA",
  particleCount = 12,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Playfair Display"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color & layout parsing
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const vignette = transparentBackground
    ? "none"
    : `radial-gradient(circle, transparent 40%, rgba(0,0,0,0.06) 100%)`;

  // Timing calculations
  const totalFrames = durationInSeconds * fps;
  
  const appearEnd = Math.floor(totalFrames * 0.1);
  const holdEnd = Math.floor(totalFrames * 0.2);
  const dissolveDuration = Math.floor(totalFrames * 0.25);

  const defAppearStart = holdEnd + Math.floor(dissolveDuration * 0.5);
  const defHoldEnd = Math.floor(totalFrames * 0.8);
  const defFadeOutEnd = Math.floor(totalFrames * 0.9);

  // Split content
  const letters = initialWord.split("");
  const words = definitionText.split(" ").filter((w) => w.length > 0);

  // Constants
  const wordAppearDuration = Math.floor(totalFrames * 0.1);
  const wordStagger = Math.floor(
    (totalFrames * 0.15) / Math.max(1, words.length)
  );

  // Typography scaling
  const mainFontSize = width * 0.085;
  const defFontSize = width * 0.038;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      <AbsoluteFill style={{ background: vignette, transition: "none" }} />

      {/* INITIAL WORD LAYER */}
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "row",
          justifyContent: "center",
          alignItems: "center",
          transition: "none",
        }}
      >
        {letters.map((letter, i) => {
          const letterStart =
            holdEnd + i * (dissolveDuration / Math.max(1, letters.length));
          const letterEnd = letterStart + dissolveDuration;

          // Initial appear
          const appearProgress = interpolate(frame, [0, appearEnd], [0, 1], {
            extrapolateRight: "clamp",
            extrapolateLeft: "clamp",
            easing: Easing.out(Easing.ease),
          });
          const initialOpacity = appearProgress;
          const initialBlur = interpolate(appearProgress, [0, 1], [15, 0]);
          const initialScale = interpolate(appearProgress, [0, 1], [0.95, 1]);

          // Dissolve
          const dissolveProgress = interpolate(
            frame,
            [letterStart, letterEnd],
            [0, 1],
            { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
          );

          const mainOpacity = interpolate(
            dissolveProgress,
            [0, 0.4, 1],
            [initialOpacity, 0, 0]
          );
          const mainBlur = interpolate(
            dissolveProgress,
            [0, 1],
            [initialBlur, 25]
          );
          const mainScale = interpolate(
            dissolveProgress,
            [0, 1],
            [initialScale, initialScale * 1.2]
          );

          // Particles generator for this letter
          const particles = Array.from({ length: particleCount }).map((_, p) => {
            const angle = random(`angle-${i}-${p}`) * Math.PI * 2;
            const dist = random(`dist-${i}-${p}`) * 300 + 50;
            const size = random(`size-${i}-${p}`) * 1.5 + 0.5;
            const isSecondary = random(`color-${i}-${p}`) > 0.5;

            const pX = interpolate(
              dissolveProgress,
              [0, 1],
              [0, Math.cos(angle) * dist],
              { easing: Easing.out(Easing.cubic) }
            );
            const pY = interpolate(
              dissolveProgress,
              [0, 1],
              [0, Math.sin(angle) * dist - 80], // drift upwards
              { easing: Easing.out(Easing.cubic) }
            );

            const pOpacity = interpolate(
              dissolveProgress,
              [0, 0.2, 1],
              [0, 0.6, 0]
            );
            const pBlur = interpolate(dissolveProgress, [0, 1], [0, 20]);
            const pScale = interpolate(
              dissolveProgress,
              [0, 1],
              [initialScale, initialScale * size * 2]
            );

            return { pX, pY, pOpacity, pBlur, pScale, isSecondary };
          });

          return (
            <div
              key={`letter-${i}`}
              style={{
                position: "relative",
                display: "inline-flex",
                justifyContent: "center",
                alignItems: "center",
                transition: "none",
              }}
            >
              <span
                style={{
                  fontFamily: "Playfair Display",
                  fontSize: mainFontSize,
                  fontWeight: 700,
                  letterSpacing: "0.15em",
                  color: textColor,
                  opacity: mainOpacity,
                  filter: `blur(${mainBlur}px)`,
                  transform: `scale(${mainScale})`,
                  display: "inline-block",
                  transition: "none",
                }}
              >
                {letter === " " ? "\u00A0" : letter}
              </span>

              {particles.map((p, pIdx) => (
                <span
                  key={`particle-${i}-${pIdx}`}
                  style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    fontFamily: "Playfair Display",
                    fontSize: mainFontSize,
                    fontWeight: 700,
                    letterSpacing: "0.15em",
                    color: p.isSecondary
                      ? secondaryParticleColor
                      : primaryParticleColor,
                    opacity: p.pOpacity,
                    filter: `blur(${p.pBlur}px)`,
                    transform: `translate(${p.pX}px, ${p.pY}px) scale(${p.pScale})`,
                    pointerEvents: "none",
                    transition: "none",
                    zIndex: 10,
                  }}
                >
                  {letter === " " ? "\u00A0" : letter}
                </span>
              ))}
            </div>
          );
        })}
      </AbsoluteFill>

      {/* DEFINITION TEXT LAYER */}
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "row",
          flexWrap: "wrap",
          justifyContent: "center",
          alignContent: "center",
          padding: `0 ${width * 0.15}px`,
          gap: `${width * 0.012}px ${width * 0.015}px`,
          transition: "none",
        }}
      >
        {words.map((word, w) => {
          const wordStart = defAppearStart + w * wordStagger;
          const wordEnd = wordStart + wordAppearDuration;

          // Fade In
          const appearProgress = interpolate(
            frame,
            [wordStart, wordEnd],
            [0, 1],
            {
              extrapolateRight: "clamp",
              extrapolateLeft: "clamp",
              easing: Easing.inOut(Easing.ease),
            }
          );

          const appearOp = interpolate(appearProgress, [0, 1], [0, 1]);
          const appearBlur = interpolate(appearProgress, [0, 1], [15, 0]);
          const appearY = interpolate(appearProgress, [0, 1], [10, 0]);

          // Fade Out
          const disappearOp = interpolate(
            frame,
            [defHoldEnd, defFadeOutEnd],
            [1, 0],
            {
              extrapolateRight: "clamp",
              extrapolateLeft: "clamp",
              easing: Easing.inOut(Easing.ease),
            }
          );
          const disappearBlur = interpolate(
            frame,
            [defHoldEnd, defFadeOutEnd],
            [0, 15],
            {
              extrapolateRight: "clamp",
              extrapolateLeft: "clamp",
              easing: Easing.in(Easing.ease),
            }
          );

          // Final State Logic
          const finalOpacity = Math.min(appearOp, disappearOp);
          const finalBlur = appearBlur + disappearBlur;

          // Converge Particles (Creates the illusion of smoke reassembling)
          const convergeParticles = Array.from({
            length: Math.max(3, Math.floor(particleCount / 2)),
          }).map((_, p) => {
            const angle = random(`w-angle-${w}-${p}`) * Math.PI * 2;
            const dist = random(`w-dist-${w}-${p}`) * 150 + 50;
            const size = random(`w-size-${w}-${p}`) * 1.2 + 0.6;
            const isSecondary = random(`w-color-${w}-${p}`) > 0.5;

            const cpX = interpolate(
              appearProgress,
              [0, 1],
              [Math.cos(angle) * dist, 0],
              { easing: Easing.out(Easing.cubic) }
            );
            const cpY = interpolate(
              appearProgress,
              [0, 1],
              [Math.sin(angle) * dist - 30, 0],
              { easing: Easing.out(Easing.cubic) }
            );

            const cpOpacity = interpolate(
              appearProgress,
              [0, 0.6, 1],
              [0, 0.35, 0]
            );
            const cpBlur = interpolate(appearProgress, [0, 1], [20, 0]);
            const cpScale = interpolate(
              appearProgress,
              [0, 1],
              [size * 1.5, 1]
            );

            return { cpX, cpY, cpOpacity, cpBlur, cpScale, isSecondary };
          });

          return (
            <div
              key={`word-${w}`}
              style={{
                position: "relative",
                display: "inline-block",
                transition: "none",
              }}
            >
              <span
                style={{
                  fontFamily: "Playfair Display",
                  fontSize: defFontSize,
                  fontWeight: 400,
                  fontStyle: "italic",
                  color: textColor,
                  opacity: finalOpacity,
                  filter: `blur(${finalBlur}px)`,
                  transform: `translateY(${appearY}px)`,
                  display: "inline-block",
                  transition: "none",
                }}
              >
                {word}
              </span>

              {/* Converge Smoke Particles */}
              {convergeParticles.map((cp, cpIdx) => (
                <span
                  key={`converge-${w}-${cpIdx}`}
                  style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    fontFamily: "Playfair Display",
                    fontSize: defFontSize,
                    fontWeight: 400,
                    fontStyle: "italic",
                    color: cp.isSecondary
                      ? secondaryParticleColor
                      : primaryParticleColor,
                    opacity: Math.min(cp.cpOpacity, disappearOp),
                    filter: `blur(${cp.cpBlur + disappearBlur}px)`,
                    transform: `translate(${cp.cpX}px, ${cp.cpY}px) scale(${cp.cpScale})`,
                    pointerEvents: "none",
                    transition: "none",
                  }}
                >
                  {word}
                </span>
              ))}
            </div>
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default InkDiffusionText;